#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<pair<int,int>> edges(m);
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        edges[i] = {a, b};
    }

    // Precompute all 21 domino types (a <= b, 1..6)
    vector<pair<int,int>> dom;
    for (int a = 1; a <= 6; ++a)
        for (int b = a; b <= 6; ++b)
            dom.push_back({a, b});
    int D = dom.size(); // 21

    int best = 0;

    // For each assignment of labels (1..6) to vertices
    int totalAssignments = 1;
    for (int i = 0; i < n; ++i) totalAssignments *= 6;

    for (int mask = 0; mask < totalAssignments; ++mask) {
        int tmp = mask;
        int label[7];
        for (int i = 0; i < n; ++i) {
            label[i] = (tmp % 6) + 1;
            tmp /= 6;
        }

        // Build list of candidate domino indices for each edge
        vector<vector<int>> edgeDom(m);
        bool ok = true;
        for (int i = 0; i < m; ++i) {
            int u = edges[i].first;
            int v = edges[i].second;
            int lu = label[u], lv = label[v];
            bool found = false;
            for (int d = 0; d < D; ++d) {
                int a = dom[d].first, b = dom[d].second;
                if ((a == lu && b == lv) || (a == lv && b == lu)) {
                    edgeDom[i].push_back(d);
                    found = true;
                }
            }
            if (!found) {
                ok = false;
                break;
            }
        }
        if (!ok) continue;

        // DP over edges with bitmask of used dominoes
        int maxMask = 1 << D;
        const int NEG_INF = -1000000;
        vector<int> dp(maxMask, NEG_INF), ndp(maxMask, NEG_INF);
        dp[0] = 0;

        for (int i = 0; i < m; ++i) {
            fill(ndp.begin(), ndp.end(), NEG_INF);
            for (int maskD = 0; maskD < maxMask; ++maskD) {
                if (dp[maskD] < 0) continue;
                // skip this edge
                ndp[maskD] = max(ndp[maskD], dp[maskD]);
                // try placing a domino
                for (int d : edgeDom[i]) {
                    if (!(maskD & (1 << d))) {
                        int nmask = maskD | (1 << d);
                        ndp[nmask] = max(ndp[nmask], dp[maskD] + 1);
                    }
                }
            }
            dp.swap(ndp);
        }

        int curBest = 0;
        for (int maskD = 0; maskD < maxMask; ++maskD)
            curBest = max(curBest, dp[maskD]);
        best = max(best, curBest);
    }

    cout << best << '\n';
    return 0;
}

