    vector<pair<int,int>> edges(m);
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        edges[i] = {a, b};
    }

    // Precompute all 21 domino types (a,b) with 1<=a<=b<=6
    vector<pair<int,int>> dom;
    for (int a = 1; a <= 6; ++a)
        for (int b = a; b <= 6; ++b)
            dom.push_back({a, b});
    int D = dom.size(); // 21

    int best = 0;

    // For each assignment of labels 1..6 to vertices (0..n-1)
    // labels[v] in [1..6]
    vector<int> labels(n);
    int totalAssignments = 1;
    for (int i = 0; i < n; ++i) totalAssignments *= 6;

    for (int mask = 0; mask < totalAssignments; ++mask) {
        int tmp = mask;
        for (int v = 0; v < n; ++v) {
            labels[v] = (tmp % 6) + 1;
            tmp /= 6;
        }

        // For this labeling, build list of usable domino types and edges
        // A domino (a,b) can be used on an edge (u,v) if {labels[u],labels[v]} = {a,b}
        // We will build bipartite graph: left = domino types [0..D-1], right = edges [0..m-1]
        // edge between d and e if compatible.
        vector<vector<int>> adj(D);
        for (int e = 0; e < m; ++e) {
            int u = edges[e].first;
            int v = edges[e].second;
            int x = labels[u], y = labels[v];
            if (x > y) swap(x, y);
            // find domino index for (x,y)
            // since dom is small, linear search is fine
            for (int d = 0; d < D; ++d) {
                if (dom[d].first == x && dom[d].second == y) {
                    adj[d].push_back(e);
                    break;
                }
            }
        }

        // Maximum bipartite matching: left size D, right size m
        vector<int> matchR(m, -1);
        int matchCount = 0;

        function<bool(int, vector<int>&)> dfs = [&](int u, vector<int>& vis) {
            for (int v : adj[u]) {
                if (vis[v]) continue;
                vis[v] = 1;
                if (matchR[v] == -1 || dfs(matchR[v], vis)) {
                    matchR[v] = u;
                    return true;
                }
            }
            return false;
        };

        for (int u = 0; u < D; ++u) {
            vector<int> vis(m, 0);
            if (dfs(u, vis)) ++matchCount;
        }

        if (matchCount > best) best = matchCount;
    }

    cout << best << '\n';
    return 0;
}

