int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<pair<int,int>> edges(m);
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        edges[i] = {a, b};
    }

    // Precompute all 21 domino types (a,b) with 1<=a<=b<=6
    vector<pair<int,int>> dom;
    for (int a = 1; a <= 6; ++a)
        for (int b = a; b <= 6; ++b)
            dom.push_back({a, b});
    int D = dom.size(); // 21

    int best = 0;

    // For each assignment of dot count to vertices: 7^n possibilities
    int maxState = 1;
    for (int i = 0; i < n; ++i) maxState *= 7; // 7^n

    for (int mask = 0; mask < maxState; ++mask) {
        // decode base-7 digits: 0..6 -> dot count 0..6 (0 means no domino incident)
        int tmp = mask;
        int dots[7];
        for (int v = 0; v < n; ++v) {
            dots[v] = tmp % 7;
            tmp /= 7;
        }

        // Build list of candidate edges that can host a domino under this assignment
        // and the required (a,b) for that edge
        vector<pair<int,int>> need; // (a,b) with a<=b
        need.reserve(m);
        for (auto &e : edges) {
            int u = e.first, v = e.second;
            int du = dots[u], dv = dots[v];
            if (du == 0 || dv == 0) continue; // no domino can be placed
            int a = du, b = dv;
            if (a > b) swap(a, b);
            need.push_back({a, b});
        }
        if (need.empty()) continue;

        // For each domino type, count how many edges need it
        int cnt[7][7];
        memset(cnt, 0, sizeof(cnt));
        for (auto &p : need) cnt[p.first][p.second]++;

        // Sum min(count,1) over all types (since only one domino per type)
        int used = 0;
        for (int a = 1; a <= 6; ++a)
            for (int b = a; b <= 6; ++b)
                if (cnt[a][b] > 0) used++;

        if (used > best) best = used;
    }

    cout << best << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<pair<int,int>> edges(m);
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        edges[i] = {a, b};
    }

    // Precompute all 21 domino types (a <= b, 1..6)
    vector<pair<int,int>> dom;
    for (int a = 1; a <= 6; ++a)
        for (int b = a; b <= 6; ++b)
            dom.push_back({a, b});
    int D = dom.size(); // 21

    int best = 0;

    // For each assignment of dot value (0..6) to each vertex (0 = unused)
    int totalStates = 1;
    for (int i = 0; i < n; ++i) totalStates *= 7;

    for (int mask = 0; mask < totalStates; ++mask) {
        int tmp = mask;
        int vdot[7];
        bool usedVertex[7];
        for (int i = 0; i < n; ++i) {
            vdot[i] = tmp % 7;
            tmp /= 7;
            usedVertex[i] = (vdot[i] != 0);
        }

        // Collect edges whose both endpoints are used
        vector<pair<int,int>> E;
        for (auto &e : edges) {
            int u = e.first, v = e.second;
            if (usedVertex[u] && usedVertex[v]) {
                int x = vdot[u], y = vdot[v];
                if (x == 0 || y == 0) continue;
                // oriented pair (x,y)
                E.push_back({x, y});
            }
        }
        if (E.empty()) continue;

        // For each domino type, we can use at most one.
        // For each oriented edge (x,y), we can use domino (min(x,y), max(x,y)) if exists.
        // But we must ensure no domino type used more than once.
        // This is maximum matching in a simple graph where each edge corresponds to a domino type.
        // However, multiple graph edges may correspond to same domino type; we can pick at most one.
        // So the answer is simply the number of distinct domino types present in E, capped by 21.

        bool present[7][7] = {};
        for (auto &p : E) {
            int x = p.first, y = p.second;
            int a = min(x, y), b = max(x, y);
            present[a][b] = true;
        }
        int cnt = 0;
        for (int a = 1; a <= 6; ++a)
            for (int b = a; b <= 6; ++b)
                if (present[a][b]) ++cnt;

        if (cnt > best) best = cnt;
    }

    cout << best << '\n';
    return 0;
}

