#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<pair<int,int>> edges(m);
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        if (a > b) swap(a, b);
        edges[i] = {a, b};
    }

    int best = 0;

    // Precompute all domino types (a,b) with 1<=a<=b<=6
    vector<pair<int,int>> dominos;
    for (int a = 1; a <= 6; ++a)
        for (int b = a; b <= 6; ++b)
            dominos.push_back({a, b});
    int D = dominos.size(); // 21

    // For each assignment of dot count (0..6) to each vertex
    // 0 means no incident domino allowed at that vertex
    int totalAssignments = 1;
    for (int i = 0; i < n; ++i) totalAssignments *= 7;

    for (int mask = 0; mask < totalAssignments; ++mask) {
        int tmp = mask;
        int c[7];
        for (int i = 0; i < n; ++i) {
            c[i] = tmp % 7;
            tmp /= 7;
        }

        // For each edge, determine if it can host a domino and what type
        // Also ensure no vertex with c[v]==0 has incident edge with c[u]!=0
        bool ok = true;
        vector<int> edgeType(m, -1); // index of domino type
        for (int i = 0; i < m && ok; ++i) {
            int u = edges[i].first;
            int v = edges[i].second;
            int cu = c[u];
            int cv = c[v];
            if (cu == 0 && cv == 0) {
                edgeType[i] = -1; // cannot place any domino
            } else if (cu == 0 || cv == 0) {
                ok = false;
                break;
            } else {
                int a = cu, b = cv;
                if (a > b) swap(a, b);
                int idx = -1;
                // map (a,b) to index in dominos
                // since D is small, linear search is fine
                for (int k = 0; k < D; ++k) {
                    if (dominos[k].first == a && dominos[k].second == b) {
                        idx = k;
                        break;
                    }
                }
                edgeType[i] = idx;
            }
        }
        if (!ok) continue;

        // Build bipartite graph: left = edges, right = domino types
        // edge exists if edgeType[i] == k
        vector<vector<int>> adj(m);
        for (int i = 0; i < m; ++i) {
            if (edgeType[i] != -1) {
                adj[i].push_back(edgeType[i]);
            }
        }

        // Maximum bipartite matching (edges -> dominos)
        vector<int> matchR(D, -1);
        int matchCount = 0;

        function<bool(int, vector<int>&)> dfs = [&](int u, vector<int> &vis) {
            for (int v : adj[u]) {
                if (vis[v]) continue;
                vis[v] = 1;
                if (matchR[v] == -1 || dfs(matchR[v], vis)) {
                    matchR[v] = u;
                    return true;
                }
            }
            return false;
        };

        for (int i = 0; i < m; ++i) {
            if (edgeType[i] == -1) continue;
            vector<int> vis(D, 0);
            if (dfs(i, vis)) ++matchCount;
        }

        if (matchCount > best) best = matchCount;
    }

    cout << best << '\n';
    return 0;
}
